    "json": "{\n  \"root\": \"main\",\n  \"state\": {\n    \"currentStep\": 2,\n    \"form\": {\n      \"companyName\": \"Tech Solutions Inc\",\n      \"industry\": \"technology\",\n      \"companySize\": \"11-50\",\n      \"website\": \"https://techsolutions.com\"\n    },\n    \"industries\": [\n      { \"value\": \"technology\", \"label\": \"Technology\" },\n      { \"value\": \"finance\", \"label\": \"Finance\" },\n      { \"value\": \"healthcare\", \"label\": \"Healthcare\" },\n      { \"value\": \"education\", \"label\": \"Education\" },\n      { \"value\": \"retail\", \"label\": \"Retail\" },\n      { \"value\": \"manufacturing\", \"label\": \"Manufacturing\" },\n      { \"value\": \"other\", \"label\": \"Other\" }\n    ],\n    \"companySizes\": [\n      { \"value\": \"1-10\", \"label\": \"1-10 employees\" },\n      { \"value\": \"11-50\", \"label\": \"11-50 employees\" },\n      { \"value\": \"51-200\", \"label\": \"51-200 employees\" },\n      { \"value\": \"200+\", \"label\": \"200+ employees\" }\n    ]\n  },\n  \"elements\": {\n    \"main\": {\n      \"type\": \"Container\",\n      \"props\": {\n        \"padding\": 24,\n        \"maxWidth\": 600\n      },\n      \"children\": [\"wizardCard\"]\n    },\n    \"wizardCard\": {\n      \"type\": \"Card\",\n      \"props\": {\n        \"title\": \"Company Details\",\n        \"subtitle\": \"Step 2 of 4\"\n      },\n      \"children\": [\"stepper\", \"form\", \"buttonGroup\"]\n    },\n    \"stepper\": {\n      \"type\": \"Stepper\",\n      \"props\": {\n        \"steps\": [\n          { \"label\": \"Personal Info\", \"status\": \"completed\" },\n          { \"label\": \"Company Details\", \"status\": \"active\" },\n          { \"label\": \"Preferences\", \"status\": \"upcoming\" },\n          { \"label\": \"Review\", \"status\": \"upcoming\" }\n        ],\n        \"current\": { \"$state\": \"/currentStep\" }\n      }\n    },\n    \"form\": {\n      \"type\": \"Form\",\n      \"props\": {\n        \"spacing\": 20,\n        \"padding\": \"24px 0\"\n      },\n      \"children\": [\"companyNameField\", \"industryField\", \"companySizeField\", \"websiteField\"]\n    },\n    \"companyNameField\": {\n      \"type\": \"FormField\",\n      \"props\": {\n        \"label\": \"Company Name\",\n        \"required\": true\n      },\n      \"children\": [\"companyNameInput\"]\n    },\n    \"companyNameInput\": {\n      \"type\": \"Input\",\n      \"props\": {\n        \"placeholder\": \"Enter your company name\",\n        \"value\": { \"$bindState\": \"/form/companyName\" }\n      }\n    },\n    \"industryField\": {\n      \"type\": \"FormField\",\n      \"props\": {\n        \"label\": \"Industry\",\n        \"required\": true\n      },\n      \"children\": [\"industrySelect\"]\n    },\n    \"industrySelect\": {\n      \"type\": \"Select\",\n      \"props\": {\n        \"placeholder\": \"Select your industry\",\n        \"options\": { \"$state\": \"/industries\" },\n        \"value\": { \"$bindState\": \"/form/industry\" }\n      }\n    },\n    \"companySizeField\": {\n      \"type\": \"FormField\",\n      \"props\": {\n        \"label\": \"Company Size\",\n        \"required\": true\n      },\n      \"children\": [\"companySizeRadio\"]\n    },\n    \"companySizeRadio\": {\n      \"type\": \"RadioGroup\",\n      \"props\": {\n        \"options\": { \"$state\": \"/companySizes\" },\n        \"value\": { \"$bindState\": \"/form/companySize\" }\n      }\n    },\n    \"websiteField\": {\n      \"type\": \"FormField\",\n      \"props\": {\n        \"label\": \"Website URL\"\n      },\n      \"children\": [\"websiteInput\"]\n    },\n    \"websiteInput\": {\n      \"type\": \"Input\",\n      \"props\": {\n        \"placeholder\": \"https://yourcompany.com\",\n        \"type\": \"url\",\n        \"value\": { \"$bindState\": \"/form/website\" }\n      }\n    },\n    \"buttonGroup\": {\n      \"type\": \"Stack\",\n      \"props\": {\n        \"direction\": \"horizontal\",\n        \"justify\": \"space-between\",\n        \"padding\": \"24px 0 0 0\"\n      },\n      \"children\": [\"backButton\", \"continueButton\"]\n    },\n    \"backButton\": {\n      \"type\": \"Button\",\n      \"props\": {\n        \"label\": \"Back\",\n        \"variant\": \"outline\"\n      },\n      \"on\": {\n        \"press\": {\n          \"action\": \"setState\",\n          \"path\": \"/currentStep\",\n          \"value\": 1\n        }\n      }\n    },\n    \"continueButton\": {\n      \"type\": \"Button\",\n      \"props\": {\n        \"label\": \"Continue\",\n        \"variant\": \"primary\"\n      },\n      \"on\": {\n        \"press\": {\n          \"action\": \"setState\",\n          \"path\": \"/currentStep\",\n          \"value\": 3\n        }\n      }\n    }\n  }\n}",
    "toon": "root: main\nstate:\n  currentStep: 2\n  form:\n    companyName:\n    industry:\n    companySize:\n    website:\nelements: [9]\n  main:\n    type: Container\n    children: [3]: stepper form buttons\n  stepper:\n    type: Stepper\n    props:\n      currentStep: 2\n      steps: [4]\n        - label: Personal Info\n          status: completed\n        - label: Company Details\n          status: active\n        - label: Preferences\n          status: upcoming\n        - label: Review\n          status: upcoming\n  form:\n    type: Form\n    children: [4]: companyField industryField sizeField websiteField\n  companyField:\n    type: FormField\n    children: [1]: companyInput\n  companyInput:\n    type: Input\n    props:\n      label: Company Name\n      placeholder: Enter company name\n      value:\n        $bindState: /form/companyName\n  industryField:\n    type: FormField\n    children: [1]: industrySelect\n  industrySelect:\n    type: Select\n    props:\n      label: Industry\n      placeholder: Select industry\n      value:\n        $bindState: /form/industry\n      options: [8]\n        - value: technology\n          label: Technology\n        - value: healthcare\n          label: Healthcare\n        - value: finance\n          label: Finance\n        - value: education\n          label: Education\n        - value: retail\n          label: Retail\n        - value: manufacturing\n          label: Manufacturing\n        - value: consulting\n          label: Consulting\n        - value: other\n          label: Other\n  sizeField:\n    type: FormField\n    children: [1]: sizeRadio\n  sizeRadio:\n    type: RadioGroup\n    props:\n      label: Company Size\n      value:\n        $bindState: /form/companySize\n      options: [4]\n        - value: 1-10\n          label: 1-10 employees\n        - value: 11-50\n          label: 11-50 employees\n        - value: 51-200\n          label: 51-200 employees\n        - value: 200+\n          label: 200+ employees\n  websiteField:\n    type: FormField\n    children: [1]: websiteInput\n  websiteInput:\n    type: Input\n    props:\n      label: Website URL\n      placeholder: https://yourcompany.com\n      value:\n        $bindState: /form/website\n  buttons:\n    type: Stack\n    props:\n      direction: horizontal\n      spacing: medium\n      align: end\n    children: [2]: backBtn continueBtn\n  backBtn:\n    type: Button\n    props:\n      label: Back\n      variant: outline\n    on:\n      press:\n        action: setState\n        path: /currentStep\n        value: 1\n  continueBtn:\n    type: Button\n    props:\n      label: Continue\n    on:\n      press:\n        action: setState\n        path: /currentStep\n        value: 3",
    "jsonTokens": 1338,
